try:
    print('>>> f = filter')
    print('>>> x = 3')
    print('>>> y = set()')
    print('>>> f(x, y)')
    f = filter
    x = 3
    y = set()
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
